import test from 'node:test'; import assert from 'node:assert/strict';
import { diagnosticOrder, transition, measurement, result, finalizeResult, report, finalizeReport, amendReport, DomainError, identifier } from '../src/domain.js';
import { TenantStore } from '../src/platform.js';
const ctx = { actorId:'user-a', organizationId:'org-a', siteId:'site-a', correlationId:'test-correlation' };
const order = () => diagnosticOrder({ ...ctx, patientId:'patient-a', serviceCode:'local-service', actorId:ctx.actorId, identifiers:[identifier({value:'ORD-1',system:'urn:test',assigningAuthority:'test',type:'order'})] });
test('order lifecycle is explicit and rejects skips', () => { const o=order(); assert.equal(transition(o,'accepted','user-a').status,'accepted'); assert.throws(()=>transition(o,'released','user-a'), DomainError); });
test('tenant store enforces organization and site isolation', () => { const s=new TenantStore(), o=order(); s.save(o,ctx); assert.equal(s.get(o.id,ctx).id,o.id); assert.throws(()=>s.get(o.id,{...ctx,organizationId:'org-b'}),DomainError); assert.throws(()=>s.get(o.id,{...ctx,siteId:'site-b'}),DomainError); assert.equal(s.audit(ctx).length,2); });
test('result and report finalization preserves immutable history through amendment', () => { const o=order(), p={source:'synthetic',createdBy:'device-a'}; const r=finalizeResult(result({orderId:o.id,patientId:o.patientId,organizationId:o.organizationId,siteId:o.siteId,measurements:[measurement({code:'local-measurement',value:1,unit:'local-unit',observedAt:new Date().toISOString(),provenance:p})],provenance:p}),'clinician'); assert.throws(()=>finalizeResult(r,'clinician'),DomainError); const final=finalizeReport(report({orderId:o.id,patientId:o.patientId,organizationId:o.organizationId,siteId:o.siteId,authorId:'clinician',content:'Synthetic finding',provenance:p}),'verifier'); const amended=amendReport(final,'clinician','Corrected synthetic finding','correction'); assert.equal(amended.supersedes,final.id); assert.equal(final.content,'Synthetic finding'); });
